//! Queue retry budget with DLQ quarantine for poison messages.
//!
//! Failing-first acceptance for the ingest queue. This file is RED until the
//! paired build slice lands: it references `nntune_ingest::retry`, which does
//! not exist yet, so this test target fails to compile while the existing
//! `--lib` and `pipeline_e2e` suites stay green.
//!
//! Do not edit this file to make it pass: implement the missing module
//! instead. The builder builds on this branch and must never edit test files.
//!
//! ## Builder contract
//! Create `workers/ingest/src/retry.rs`, exposed as `pub mod retry` from
//! `lib.rs`:
//!
//! ```ignore
//! pub const RETRY_MAX_ATTEMPTS: u32; // total deliveries incl. first; == jobs::MAX_ATTEMPTS
//! pub const DLQ_QUEUE_NAME: &str;    // == "nntune-ingest-dlq"
//! pub const MAX_RETRY_DELAY_MS: u64; // ceiling for retry_delay_ms
//!
//! pub fn should_retry(attempt: u32) -> bool;
//! // true while another delivery is allowed (attempt is 1-based, as in
//! // QueueMsg::attempt). Must match jobs::can_retry semantics:
//! // true for 1..RETRY_MAX_ATTEMPTS, false for 0, MAX and above.
//!
//! pub fn retry_delay_ms(attempt: u32) -> u64;
//! // Backoff before the next delivery for the attempt that just failed.
//! // Increasing over 1..MAX, always > 0, always <= MAX_RETRY_DELAY_MS,
//! // saturating (any u32 maps to a sane delay).
//!
//! pub struct DlqEntry {
//!     pub original: QueueMsg,
//!     pub attempts: u32,   // deliveries spent (== original.attempt at quarantine)
//!     pub code: String,     // stable failure code, non-empty
//!     pub reason: String,   // human reason, non-empty
//! }
//!
//! pub fn quarantine(msg: &QueueMsg, code: &str, reason: &str) -> DlqEntry;
//! // Attempts comes from msg.attempt; code/reason are stored verbatim.
//!
//! pub fn dlq_reason_headers(entry: &DlqEntry) -> Vec<(String, String)>;
//! // Must contain, at minimum, these exact keys:
//! //   "x-ingest-dlq-attempts"    (decimal, == entry.attempts)
//! //   "x-ingest-dlq-code"        (== entry.code)
//! //   "x-ingest-dlq-reason"      (== entry.reason)
//! //   "x-ingest-dlq-job"         (== entry.original.job_id)
//! //   "x-ingest-dlq-idempotency" (== entry.original.idempotency_key)
//!
//! pub fn redrive(entry: DlqEntry) -> QueueMsg;
//! // Moves a quarantined message back to the queue: attempt reset to 1,
//! // job/user/idempotency/source/input/payload preserved.
//!
//! pub struct AttemptReport {
//!     pub msg: QueueMsg,
//!     pub succeeded: bool,
//!     pub code: String,   // failure code when !succeeded
//!     pub reason: String, // failure reason when !succeeded
//! }
//! pub struct BatchOutcome {
//!     pub completed: Vec<QueueMsg>,
//!     pub to_retry: Vec<(QueueMsg, u64)>, // (msg, delay_ms)
//!     pub quarantined: Vec<DlqEntry>,
//! }
//! pub fn decide_batch(reports: Vec<AttemptReport>) -> BatchOutcome;
//! // Per-message routing, never batch-aborting:
//! //   succeeded -> completed
//! //   failed + should_retry(attempt) -> to_retry with retry_delay_ms(attempt)
//! //   failed + !should_retry(attempt) -> quarantined via quarantine()
//! // Input order is preserved within each output vec.
//! ```
//!
//! README contract: `workers/ingest/README.md` must document the redrive path
//! (mentions "redrive", "dlq", and the DLQ queue name). The wrangler example
//! already names the DLQ queue; `DLQ_QUEUE_NAME` must match it and
//! `RETRY_MAX_ATTEMPTS - 1` must match the consumer `max_retries` (4) and
//! `dispatch::PAYLOAD_RETRY_ATTEMPTS`.

use nntune_ingest::dispatch::{build_upload_dispatch, PAYLOAD_RETRY_ATTEMPTS};
use nntune_ingest::fixtures::SMALL_NZB;
use nntune_ingest::jobs::{can_retry, MAX_ATTEMPTS};
use nntune_ingest::queue::QueueMsg;
use nntune_ingest::retry::{
    decide_batch, dlq_reason_headers, quarantine, redrive, retry_delay_ms, should_retry,
    AttemptReport, DLQ_QUEUE_NAME, MAX_RETRY_DELAY_MS, RETRY_MAX_ATTEMPTS,
};
use std::collections::HashMap;

const USER: &str = "user_01";
const POISON_CODE: &str = "PROBE_TIMEOUT";
const POISON_REASON: &str = "pool probe timed out on every delivery";

fn valid_msg() -> QueueMsg {
    build_upload_dispatch(USER, SMALL_NZB).expect("fixture must dispatch")
}

fn msg_at_attempt(attempt: u32) -> QueueMsg {
    let mut msg = valid_msg();
    msg.attempt = attempt;
    msg
}

fn report(msg: QueueMsg, succeeded: bool) -> AttemptReport {
    AttemptReport {
        msg,
        succeeded,
        code: if succeeded {
            String::new()
        } else {
            POISON_CODE.to_string()
        },
        reason: if succeeded {
            String::new()
        } else {
            POISON_REASON.to_string()
        },
    }
}

fn headers_map(entry: &nntune_ingest::retry::DlqEntry) -> HashMap<String, String> {
    dlq_reason_headers(entry).into_iter().collect()
}

// --- retry budget -----------------------------------------------------------

#[test]
fn retry_budget_is_bounded() {
    assert!(should_retry(1), "first delivery may retry");
    assert!(
        should_retry(RETRY_MAX_ATTEMPTS - 1),
        "last retryable attempt may retry"
    );
    assert!(!should_retry(0), "attempt is 1-based");
    assert!(
        !should_retry(RETRY_MAX_ATTEMPTS),
        "budget spent: must quarantine, not retry"
    );
    assert!(!should_retry(RETRY_MAX_ATTEMPTS + 1));
    assert!(!should_retry(u32::MAX));
}

#[test]
fn retry_budget_matches_job_and_payload_budgets() {
    assert_eq!(
        RETRY_MAX_ATTEMPTS, MAX_ATTEMPTS,
        "queue budget and job budget must agree"
    );
    assert_eq!(
        RETRY_MAX_ATTEMPTS - 1,
        PAYLOAD_RETRY_ATTEMPTS,
        "queue redeliveries must match the payload retry slots"
    );
    // Same boundary as the job-level gate.
    for attempt in 0..RETRY_MAX_ATTEMPTS + 2 {
        assert_eq!(
            should_retry(attempt),
            can_retry(attempt),
            "attempt {attempt}: queue and job gates must agree"
        );
    }
}

#[test]
fn retry_backoff_is_bounded_increasing_and_saturating() {
    let d1 = retry_delay_ms(1);
    let d2 = retry_delay_ms(2);
    let d3 = retry_delay_ms(RETRY_MAX_ATTEMPTS - 1);
    assert!(d1 > 0, "first retry must wait");
    assert!(d2 > d1, "backoff must increase");
    assert!(d3 > d2, "backoff must keep increasing to the budget edge");
    for attempt in 1..=RETRY_MAX_ATTEMPTS + 1 {
        let d = retry_delay_ms(attempt);
        assert!(
            d <= MAX_RETRY_DELAY_MS,
            "attempt {attempt}: delay {d} over ceiling {MAX_RETRY_DELAY_MS}"
        );
    }
    assert_eq!(
        retry_delay_ms(u32::MAX),
        MAX_RETRY_DELAY_MS,
        "huge attempts must saturate at the ceiling"
    );
    assert_eq!(
        retry_delay_ms(1_000_000),
        MAX_RETRY_DELAY_MS,
        "far-future attempts must saturate at the ceiling"
    );
}

// --- poison quarantine ------------------------------------------------------

#[test]
fn always_failing_job_exhausts_budget_into_dlq() {
    // Simulate the consumer: every delivery of this job fails. Early
    // failures retry; the failure at the budget edge quarantines.
    let mut msg = msg_at_attempt(1);
    for attempt in 1..RETRY_MAX_ATTEMPTS {
        assert!(
            should_retry(msg.attempt),
            "attempt {attempt} must still retry"
        );
        let delay = retry_delay_ms(msg.attempt);
        assert!(delay > 0 && delay <= MAX_RETRY_DELAY_MS);
        msg.attempt += 1;
    }
    assert_eq!(msg.attempt, RETRY_MAX_ATTEMPTS);
    assert!(!should_retry(msg.attempt), "budget spent: no further retry");
    let entry = quarantine(&msg, POISON_CODE, POISON_REASON);
    assert_eq!(entry.attempts, RETRY_MAX_ATTEMPTS);
    assert_eq!(entry.code, POISON_CODE);
    assert_eq!(entry.reason, POISON_REASON);
    assert_eq!(entry.original.job_id, msg.job_id);
    assert_eq!(entry.original.idempotency_key, msg.idempotency_key);
}

#[test]
fn dlq_entry_carries_reason_headers() {
    let msg = msg_at_attempt(RETRY_MAX_ATTEMPTS);
    let entry = quarantine(&msg, POISON_CODE, POISON_REASON);
    let headers = headers_map(&entry);
    assert_eq!(
        headers.get("x-ingest-dlq-attempts").map(String::as_str),
        Some(RETRY_MAX_ATTEMPTS.to_string().as_str()),
        "headers must carry the spent attempt count"
    );
    assert_eq!(
        headers.get("x-ingest-dlq-code").map(String::as_str),
        Some(POISON_CODE),
        "headers must carry the failure code"
    );
    assert_eq!(
        headers.get("x-ingest-dlq-reason").map(String::as_str),
        Some(POISON_REASON),
        "headers must carry the failure reason"
    );
    assert_eq!(
        headers.get("x-ingest-dlq-job").map(String::as_str),
        Some(msg.job_id.as_str()),
        "headers must name the job"
    );
    assert_eq!(
        headers.get("x-ingest-dlq-idempotency").map(String::as_str),
        Some(msg.idempotency_key.as_str()),
        "headers must carry the idempotency key"
    );
    // Every value renders (no empty headers on a quarantined job).
    for (k, v) in dlq_reason_headers(&entry) {
        assert!(!k.is_empty() && !v.is_empty(), "header {k:?} must render");
    }
}

// --- poison does not block valid jobs ---------------------------------------

#[test]
fn valid_jobs_behind_poison_still_process() {
    // One poison message at the budget edge plus two valid jobs behind it in
    // the same batch: the valid jobs must complete while the poison
    // quarantines. A consumer that aborts the batch on first failure drops
    // this test's completions.
    let poison = msg_at_attempt(RETRY_MAX_ATTEMPTS);
    let poison_id = poison.job_id.clone();
    let first = valid_msg();
    let second = valid_msg();
    let first_id = first.job_id.clone();
    let second_id = second.job_id.clone();
    let outcome = decide_batch(vec![
        report(poison, false),
        report(first, true),
        report(second, true),
    ]);
    assert_eq!(outcome.completed.len(), 2, "both valid jobs must complete");
    assert_eq!(outcome.quarantined.len(), 1, "poison must quarantine");
    assert!(outcome.to_retry.is_empty());
    let completed_ids: Vec<&str> = outcome
        .completed
        .iter()
        .map(|m| m.job_id.as_str())
        .collect();
    assert_eq!(completed_ids, vec![first_id.as_str(), second_id.as_str()]);
    assert_eq!(outcome.quarantined[0].original.job_id, poison_id);
    assert_eq!(outcome.quarantined[0].attempts, RETRY_MAX_ATTEMPTS);
}

#[test]
fn retryable_failure_retries_while_valid_jobs_complete() {
    // Same batch shape one delivery earlier: the poison retries (with a
    // backoff delay) instead of quarantining, and the valid jobs still
    // complete in the same batch.
    let poison = msg_at_attempt(1);
    let expected_delay = retry_delay_ms(1);
    let outcome = decide_batch(vec![
        report(poison, false),
        report(valid_msg(), true),
        report(valid_msg(), true),
    ]);
    assert_eq!(outcome.completed.len(), 2);
    assert_eq!(outcome.to_retry.len(), 1, "early failure must retry");
    assert!(outcome.quarantined.is_empty(), "early failure must not DLQ");
    assert_eq!(outcome.to_retry[0].1, expected_delay);
}

#[test]
fn batch_routing_is_per_message_and_order_preserving() {
    // Interleaved outcomes route independently; each output vec keeps input
    // order so redelivery and DLQ tooling can correlate by position.
    let ok_a = valid_msg();
    let fail_retry = msg_at_attempt(2);
    let ok_b = valid_msg();
    let fail_dlq = msg_at_attempt(RETRY_MAX_ATTEMPTS);
    let ok_a_id = ok_a.job_id.clone();
    let ok_b_id = ok_b.job_id.clone();
    let outcome = decide_batch(vec![
        report(ok_a, true),
        report(fail_retry.clone(), false),
        report(ok_b, true),
        report(fail_dlq, false),
    ]);
    assert_eq!(outcome.completed.len(), 2);
    assert_eq!(outcome.to_retry.len(), 1);
    assert_eq!(outcome.quarantined.len(), 1);
    assert_eq!(outcome.completed[0].job_id, ok_a_id);
    assert_eq!(outcome.completed[1].job_id, ok_b_id);
    assert_eq!(outcome.to_retry[0].0.job_id, fail_retry.job_id);
    assert_eq!(outcome.to_retry[0].1, retry_delay_ms(2));
}

// --- redrive ----------------------------------------------------------------

#[test]
fn redrive_returns_quarantined_job_to_the_queue() {
    let poison = msg_at_attempt(RETRY_MAX_ATTEMPTS);
    let entry = quarantine(&poison, POISON_CODE, POISON_REASON);
    let back = redrive(entry);
    assert_eq!(back.attempt, 1, "redriven job restarts the budget");
    assert_eq!(back.job_id, poison.job_id);
    assert_eq!(back.idempotency_key, poison.idempotency_key);
    assert_eq!(back.user_id, poison.user_id);
    assert_eq!(back.source, poison.source);
    assert_eq!(back.payload_ref, poison.payload_ref);
    assert!(
        should_retry(back.attempt),
        "redriven job must be retryable again"
    );
}

// --- config and docs --------------------------------------------------------

#[test]
fn dlq_name_matches_consumer_config() {
    assert_eq!(DLQ_QUEUE_NAME, "nntune-ingest-dlq");
    let text = find_workspace_file("workers/ingest/wrangler.toml.example");
    assert!(
        text.contains(DLQ_QUEUE_NAME),
        "wrangler example must name the DLQ queue {DLQ_QUEUE_NAME:?}"
    );
    assert!(
        text.contains("max_retries = 4"),
        "consumer max_retries must stay 4 (== RETRY_MAX_ATTEMPTS - 1)"
    );
    assert_eq!(RETRY_MAX_ATTEMPTS - 1, 4);
}

#[test]
fn readme_documents_the_redrive_path() {
    let text = find_workspace_file("workers/ingest/README.md");
    let lower = text.to_lowercase();
    assert!(
        lower.contains("redrive"),
        "README must document the redrive path"
    );
    assert!(lower.contains("dlq"), "README must name the DLQ");
    assert!(
        text.contains(DLQ_QUEUE_NAME),
        "README must name the DLQ queue {DLQ_QUEUE_NAME:?}"
    );
}

fn find_workspace_file(rel: &str) -> String {
    let mut dir = std::env::current_dir().expect("cwd");
    for _ in 0..8 {
        let cand = dir.join(rel);
        if cand.is_file() {
            return std::fs::read_to_string(&cand).expect("read workspace file");
        }
        if !dir.pop() {
            break;
        }
    }
    panic!("{rel} not found above {:?}", std::env::current_dir());
}
